def check_n(n, a_0, max_k=20):
    a = [0] * (max_k + 1)
    a[0] = a_0
    for k in range(1, max_k + 1):
        a[k] = a[k-1] / k + k**(n-1)
        if not a[k].is_integer():
            return False
    return True

for n in range(1, 11):
    found = False
    for a_0 in range(-1000, 1000):
        if check_n(n, a_0):
            print(f"n={n}, a_0={a_0}")
            found = True
            break
    if not found:
        print(f"n={n}: No solution found")

def check_n_exists(n, max_k=20):
    # c_{k-1} = (k+1)c_k - k^{n-1}
    # we need c_k to be integers for all k >= 1
    # let's find c_k by working backwards from some large K
    # we need c_k to be an integer for all k >= 1
    # so c_K, c_{K-1}, ..., c_1, c_0 must all be integers
    # let's try to see if we can find such a sequence
    for cK in range(-100, 100):
        c = [0] * (max_k + 1)
        c[max_k] = cK
        for k in range(max_k, 1, -1):
            # c_{k-1} = (k+1)c_k - k^{n-1}
            # Wait, k is the index. So c_{k-1} = (k+1)c_k - k^{n-1}
            c[k-1] = (k+1) * c[k] - k**(n-1)

        # Check if all c_k are integers (they are)
        # and then check if m_k = (k+1)c_k are integers (they are)
        # and then check if a_k = m_k are integers (they are)
        # and then check if a_k = a_{k-1}/k + k^{n-1}
        # a_k = m_k. So m_k = m_{k-1}/k + k^{n-1}.
        # This is c_k (k+1) = (c_{k-1} k) / k + k^n ... no.
        # Let's just check the recurrence a_k = a_{k-1}/k + k^{n-1}.
        a = [0] * (max_k + 1)
        a[0] = c[0] # Wait, m_1 = a_0 + 1, so a_0 = m_1 - 1 = 2c_1 - 1.
        # Let's use m_k = (k+1)c_k
        m = [0] * (max_k + 1)
        for k in range(1, max_k + 1):
            m[k] = (k+1) * c[k]

        a[0] = m[1] - 1
        for k in range(1, max_k + 1):
            a[k] = a[k-1] / k + k**(n-1)
            if not a[k].is_integer():
                break
        else:
            return True, a[0]
    return False, None

for n in range(1, 11):
    exists, a0 = check_n_exists(n)
    if exists:
        print(f"n={n}, a0={a0}")
    else:
        print(f"n={n}: No solution")
